[web] Search Trends
Returns search volume trends for keywords linked to a topic seed or a keyword group, both as an aggregate across all keywords and broken down per individual keyword over time.

```ts
mcp__Similarweb__get_demand_search_trends(args: {
// Granularity
//
// Time granularity for the returned values **Constraints:** supports only monthly for the last 3 months, or daily granularity for the last 28 days only
granularity?: "daily" | "monthly", // default: null
// Country
//
// Two-letter country code (e.g., 'us', 'gb', 'ww')
country: string,
// Start Date
//
// Start date in 'YYYY-MM' or 'YYYY-MM-DD' format or relative keywords: latest, X_months_ago, X_days_ago
start_date?: string, // default: null
// End Date
//
// End date in 'YYYY-MM' or 'YYYY-MM-DD' format or relative keywords: latest, X_months_ago, X_days_ago
end_date?: string, // default: null
// Topic
//
// Topic seed (free-form text). Mutually exclusive with 'keyword_group'. **Constraints:** Either 'topic' or 'keyword_group' must be provided, but not both
topic?: string, // default: null
// Keyword Group
//
// Keyword group ID in GUID format. Mutually exclusive with 'topic'. **Constraints:** Either 'topic' or 'keyword_group' must be provided, but not both
keyword_group?: string, // default: null
// Format
//
// Format in which the reply should be returned
format?: "json" | "xml", // default: null
}): Promise<unknown>;
```

