// `none` keeps Spaces with no named primary contact, where the team admins are the contact. Combines with access and the other filters.
contact?: "all" | "none", // default: "all"
// Opaque cursor from the previous page's `nextCursor`.
cursor?: string, // minLength: 1, maxLength: 4096
direction?: "asc" | "desc", // default: "desc"
// Page size.
limit?: integer, // default: 20, minimum: 1, maximum: 100
// Only Spaces whose last edit is at least this many days ago.
notEditedInDays?: integer, // minimum: 1, maximum: 3650
