// Match the Space title, or the contact's name or email.
q?: string, // maxLength: 200
// Order by last edit, Space title, owning team name, or contact name. Spaces without a contact sort as an empty name. A cursor only continues the sort and direction it came from.
sort?: "edited" | "title" | "team" | "contact", // default: "edited"
teamId: string, // minLength: 1
}): Promise<unknown>;
